	corner(titleGrad, 16)
	grad(titleGrad, 0)

	-- Bottom border accent line under title bar
	local titleLine = mk("Frame", {
		Size = UDim2.new(1, 0, 0, 2),
		Position = UDim2.new(0, 0, 1, -2),
